    dosage_value_max numeric(10,4),
    dosage_unit character varying(20),
    dosage_area_value numeric(10,4),
    dosage_area_unit character varying(20),
    mixing_instruction text,
    water_volume_min numeric(10,2),
    water_volume_max numeric(10,2),
    water_volume_unit character varying(10),
    spray_times smallint,
    spray_interval character varying(100) NOT NULL,
    application_method text,
