-- Name: treatment_weather_condition; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.treatment_weather_condition (
    id integer NOT NULL,
    created_at timestamp(6) without time zone,
    created_by integer,
    deleted_at timestamp(6) without time zone,
    deleted_by integer,
    is_delete boolean,
    updated_at timestamp(6) without time zone,
    updated_by integer,
    is_required boolean,
    max_value numeric(10,2),
    min_value numeric(10,2),
    operator character varying(255),
    recommendation_note text,
    unit text,
    weather_factor character varying(255),
    treatment_id integer,
    CONSTRAINT treatment_weather_condition_operator_check CHECK (((operator)::text = ANY ((ARRAY['GREATER_THAN'::character varying, 'LESS_THAN'::character varying, 'BETWEEN'::character varying, 'EQUALS'::character varying])::text[]))),
    CONSTRAINT treatment_weather_condition_weather_factor_check CHECK (((weather_factor)::text = ANY ((ARRAY['TEMPERATURE'::character varying, 'HUMIDITY'::character varying, 'RAINFALL'::character varying])::text[])))
);


ALTER TABLE public.treatment_weather_condition OWNER TO postgres;

